        vm.assume(_newOwner != address(this));
        vm.prank(address(this));
        c.transferOwnership(_newOwner);
        // General rule: after transferOwnership, c.owner() must equal the passed _newOwner
        assertTrue(c.owner() == _newOwner);
    }
}

