pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // 1. Restrict: newOwner must differ from the default owner (address(0) + deployer) to witness the change
        vm.assume(newOwner != address(0) && newOwner != address(this));

        // 2. The current owner (deployer) initiates the transfer to newOwner
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // 3. Assert that newOwner can now call a function protected by onlyOwner.
        //    The reference updates owner to newOwner, so the call succeeds (returns true).
        //    The mutant leaves owner unchanged (still the deployer), so the call from newOwner reverts (returns false).
        vm.prank(newOwner);
        bool ok = true;
        try c.owned() {} catch { ok = false; }
        assertTrue(ok);
    }
}

